<?php
require_once __DIR__ . '/includes/course_unlock.php';
header('Cache-Control: private, no-store');
$pdo=db();$who=current_user();$sid=$who&&$who['role']===ROLE_STUDENT?(int)$who['id']:null;
$id=positive_int($_GET['id']??$_POST['course_id']??null);
if($id<1||!bf_course_unlocked($pdo,$id,$sid)){http_response_code(404);exit('Khóa học chưa được mở khóa hoặc chưa công khai. <a href="'.e(app_url('courses.php')).'">Trở về danh mục</a>');}
$st=$pdo->prepare("SELECT c.*,u.full_name teacher_name FROM courses c JOIN users u ON u.id=c.teacher_id WHERE c.id=:id AND c.status='published'");$st->execute(['id'=>$id]);$c=$st->fetch(PDO::FETCH_ASSOC);
if(!$c){http_response_code(404);exit('Không tìm thấy khóa học.');}
$enrolled=false;
if($sid){$st=$pdo->prepare("SELECT id,status FROM enrollments WHERE student_id=:sid AND course_id=:cid LIMIT 1");$st->execute(['sid'=>$sid,'cid'=>$id]);$en=$st->fetch(PDO::FETCH_ASSOC);$enrolled=$en&&$en['status']!=='cancelled';}
$error='';
if(is_post()){
  require_csrf();
  if(!$sid){redirect('login.php');}
  if(($_POST['action']??'')!=='enroll'){$error='Yêu cầu không hợp lệ.';}
  elseif(!$enrolled){
    try{$pdo->beginTransaction();
      $lock=$pdo->prepare('SELECT status FROM courses WHERE id=:id FOR UPDATE');$lock->execute(['id'=>$id]);
      if($lock->fetchColumn()!=='published'||!bf_course_unlocked($pdo,$id,$sid))throw new RuntimeException('Khóa học chưa được mở khóa.');
      $st=$pdo->prepare("INSERT INTO enrollments(student_id,course_id,status) VALUES(:sid,:cid,'active') ON DUPLICATE KEY UPDATE completed_at=IF(status='cancelled',NULL,completed_at),status=IF(status='cancelled','active',status)");
      $st->execute(['sid'=>$sid,'cid'=>$id]);$pdo->commit();redirect('student/learn.php?course_id='.$id);
    }catch(Throwable $exc){if($pdo->inTransaction())$pdo->rollBack();error_log('[BrightFuture enrollment] '.$exc->getMessage());$error='Không đăng ký được, vui lòng kiểm tra lại.';}
  }
}
$st=$pdo->prepare("SELECT ch.title chapter_title,l.id,l.title,l.duration_minutes,l.is_preview FROM course_chapters ch LEFT JOIN lessons l ON l.chapter_id=ch.id AND l.status='published' WHERE ch.course_id=:id ORDER BY ch.position,ch.id,l.position,l.id");$st->execute(['id'=>$id]);$ls=$st->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($c['title'])?> - BrightFuture</title><style>body{margin:0;background:#f4f6fd;color:#17223b;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}.top{background:#fff;border-bottom:1px solid #e0e5ee;padding:17px 5%;display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.top a{color:#4f46e5;text-decoration:none;margin-right:15px;font-weight:600}.wrap{max-width:1140px;margin:32px auto;padding:0 18px}h1{font-size:29px;margin:0 0 12px}p{color:#64748b;line-height:1.6}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.toolbar input,.toolbar select,.form input,.form select{padding:11px;border:1px solid #d5dce9;border-radius:9px;background:#fff;max-width:100%}.toolbar input{flex:1;min-width:220px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.card{background:#fff;border:1px solid #e0e5ee;border-radius:15px;overflow:hidden}.image{width:100%;height:150px;object-fit:cover;background:#e0e7ff}.card-body{padding:20px}.card h2{font-size:19px;margin:8px 0}.tag{font-size:12px;color:#3730a3;background:#e7e8ff;border-radius:100px;padding:5px 10px}.button{display:inline-block;padding:10px 16px;border:0;background:#5046e5;color:#fff!important;border-radius:9px;text-decoration:none;font-weight:600;cursor:pointer}.button.secondary{background:#eef0ff;color:#3730a3!important}.notice{padding:15px;background:#fff7ed;border:1px solid #fed7aa;border-radius:10px;margin:15px 0}.success{background:#ecfdf5;border-color:#a7f3d0}.form{background:#fff;padding:22px;border:1px solid #e0e5ee;border-radius:14px;max-width:700px}.form label{display:block;margin:13px 0;font-weight:600}.form input,.form select{display:block;width:100%;margin-top:6px}.small{font-size:13px}.chapter{background:#fff;border:1px solid #e0e5ee;border-radius:12px;padding:18px;margin:12px 0}.lesson{padding:10px;border-top:1px solid #eef1f6}.lesson a{color:#4f46e5;text-decoration:none}@media(max-width:650px){.top{padding:13px}.wrap{margin:20px auto}h1{font-size:23px}}</style></head><body><header class="top"><strong>🎓 BrightFuture</strong><nav><a href="<?=e(app_url('courses.php'))?>">Khám phá</a><a href="<?=e(app_url('student/my-courses.php'))?>">Khóa học của tôi</a></nav></header><main class="wrap"><a href="<?=e(app_url('courses.php'))?>">← Trở về danh mục</a><h1 style="margin-top:20px"><?=e($c['title'])?></h1><p>Giảng viên: <?=e($c['teacher_name'])?> · Trình độ <?=e(['beginner'=>'Cơ bản','intermediate'=>'Trung bình','advanced'=>'Nâng cao'][$c['level']]??$c['level'])?></p><p><?=nl2br(e((string)$c['description']))?></p><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif?><?php if($enrolled):?><a class="button" href="<?=e(app_url('student/learn.php?course_id='.$id))?>">▶ Vào học ngay</a><?php elseif(!$sid):?><a class="button" href="<?=e(app_url('login.php'))?>">Đăng nhập để đăng ký</a><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="course_id" value="<?=$id?>"><input type="hidden" name="action" value="enroll"><button class="button" type="submit">Đăng ký khóa học</button></form><?php endif?><h2>Danh sách bài giảng</h2><?php $last='';foreach($ls as $l):if($last!==$l['chapter_title']):$last=$l['chapter_title'];?><h3><?=e($last)?></h3><?php endif;if(!$l['id'])continue;?><div class="chapter">▶ <?=e($l['title'])?> · <?= (int)$l['duration_minutes']?> phút <?php if($enrolled):?><a style="float:right" href="<?=e(app_url('student/learn.php?id='.(int)$l['id']))?>">Xem bài</a><?php endif?></div><?php endforeach?></main></body></html>
